async function movePoints(from, to, n) {
  await pool.query('BEGIN');
  await pool.query(
    'UPDATE accounts SET points = points - $1 WHERE id = $2', [n, from]);
  await pool.query(
    'UPDATE accounts SET points = points + $1 WHERE id = $2', [n, to]);
  await pool.query('COMMIT');
}
